/* From Uiverse.io by hayyangovinda  - Tags: flashy, checkbox, clock, days, alarm */
.__UIV_SCOPE__ .days-btn-container {
  display: flex;
  width: 300px;
  align-items: center;
  justify-content: space-evenly;
  height: 34px;
}

.__UIV_SCOPE__ .day-btn {
  display: none; /* Hide the original checkbox */
}

.__UIV_SCOPE__ .day-label {
  background-color: transparent;
  font-size: 11px;
  font-weight: 600;
  color: #ff5b22;
  cursor: pointer;
  border: 2px solid #ff5b22;
  border-radius: 50%;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 5px;
}

/* Apply styles for the selected state */
.__UIV_SCOPE__ .day-btn:checked + .day-label {
  background-color: #ffe53b;
  background-image: linear-gradient(147deg, #ffe53b 0%, #ff2525 74%);
  border: none;
  color: white;
}
